  "settings.commandline.trustCaution": "في هذا الوضع، يمكن لأي برنامج على الأجهزة المسموح بها، بما في ذلك الوكلاء الذين يعملون هنا، التحكم في Polyth بصفتك، بما في ذلك الموافقة على إجراءات الوكلاء. لا يتم الوثوق أبدًا بالطلبات الواردة عبر وكيل عكسي (reverse proxy) أو من متصفح. يُقصد بـ \"الشبكة الخاصة\" عناوين الشبكة المحلية (10.x، 172.16–31.x، 192.168.x)، وليس شبكات VPN أو الشبكات التراكبية.",
