  "shellintro.kicker": "جولة في الواجهة",
  "shellintro.stepCount": "{step} من {total}",
  "shellintro.steps": "خطوات الجولة",
  "shellintro.goToStep": "الانتقال إلى الخطوة {step} من {total}",
  "shellintro.start": "أرني",
  "shellintro.skip": "تخطي الجولة",
  "shellintro.finish": "ابدأ العمل",
  "shellintro.menuEntry": "جولة في الواجهة",
  "shellintro.addProjectNow": "أضف مشروعًا الآن",
  "shellintro.addProjectResumeNote": "تستمر الجولة عندما تنتهي.",
  "shellintro.projectReadyTitle": "مشروعك جاهز",
  "shellintro.projectReadyBody": "ها هو. ما دام محددًا، تستطيع المحادثات الجديدة رؤية ملفاته والعمل عليها. انقر على مشروع في هذه القائمة للتنقل بين المشاريع.",
  "shellintro.projectReadyPhoneBody": "أصبح الآن في هذه القائمة. ما دام محددًا، تستطيع المحادثات الجديدة رؤية ملفاته والعمل عليها. المس هنا في أي وقت لتبديل المشروع.",
  "shellintro.openAppearance": "افتح المظهر",
  "shellintro.welcomeTitle": "مرحبًا بك في Polyth",
  "shellintro.welcomeBody": "يمكنك البدء فورًا — لا شيء يحتاج إلى إعداد، ولا يمكنك إفساد أي شيء. تُريك هذه الجولة التي تستغرق دقيقة أين تكتب، وأين تُحفظ محادثاتك، وكيف تغيّر الأشياء لاحقًا.",
  "shellintro.startTitle": "ابدأ من هنا مباشرة",
  "shellintro.startBody": "اكتب ما تحتاجه بكلماتك الخاصة — سؤالًا أو مهمة أو مسودة — ثم أرسله. تظهر الإجابة هنا تمامًا. محادثاتك لا يراها أحد غيرك.",
  "shellintro.projectsTitle": "المحادثات والمشاريع",
  "shellintro.projectsBody": "تُحفظ هنا كل محادثاتك، لتعود إلى أي منها. والمشاريع التي تضيفها لاحقًا تظهر هنا أيضًا، ولكل منها محادثاته. تعني النقطة الصغيرة أن المساعد يعمل أو ينتظر ردّك.",
  "shellintro.addProjectTitle": "المشاريع، عندما تحتاج إليها",
  "shellintro.addProjectBody": "لا تحتاج إلى مشروع لتبدأ. المشروع ببساطة مجلد يضم ملفاتك — مستندات أو صورًا أو موقعًا إلكترونيًا أو شيفرة. أضف مشروعًا، وسيتمكن المساعد من فتح هذه الملفات وتعديلها عندما تطلب. (يستطيع المطوّرون أيضًا ربط مستودع Git أو حاسوب آخر عبر SSH.)",
  "shellintro.topRailTitle": "أدوات في الأعلى",
  "shellintro.topRailBody": "أزرار لأدواتك. تُفتح كل أداة بجانب المحادثة، فيبقى الحديث أمامك.",
  "shellintro.rightRailTitle": "مزيد من الأدوات على الجانب",
  "shellintro.rightRailBody": "مزيد من الأدوات، بما فيها الإضافات التي تثبّتها. تُفتح كل أداة في لوحة جانبية؛ اسحب حافتها لتوسيعها.",
  "shellintro.toolsTitle": "الأدوات",
  "shellintro.dragTitle": "ضع الأزرار حيث تشاء",
  "shellintro.dragBody": "اسحب زرًا لنقله على شريطه أو إلى شريط آخر. لإزالته اسحبه بعيدًا ثم اتركه — ويمكنك إعادته لاحقًا. على شاشة اللمس اضغط مطولًا أولًا.",
  "shellintro.customizeTitle": "وظائف على طريقتك",
  "shellintro.customizeBody": "افتح القائمة التي يشير إليها السهم وفعّل «وضع التعديل»: يظهر قلم في كل جزء من الشاشة لإضافة الأزرار والأدوات المصغّرة أو إزالتها أو نقلها. وباقي الخيارات في الإعدادات: المساعدون ونماذج الذكاء الاصطناعي، والإضافات (الحزم)، واختصارات لوحة المفاتيح.",
  "shellintro.appearanceTitle": "مظهر على ذوقك",
  "shellintro.appearanceBody": "من الإعدادات ← المظهر اختر الألوان، والوضع الفاتح أو الداكن، وحجم النص، والخطوط، وخلفية الشاشة وغيرها. ويمكن أن يكون لكل مشروع أيقونته الخاصة.",
  "shellintro.projectsPhoneTitle": "المحادثات والمشاريع",
  "shellintro.projectsPhoneBody": "المس هنا لترى محادثاتك. والمشاريع التي تضيفها لاحقًا تظهر هنا أيضًا. تعني النقطة الصغيرة أن المساعد يعمل أو ينتظر ردّك.",
  "shellintro.addProjectPhoneBody": "لا تحتاج إلى مشروع لتبدأ. المشروع ببساطة مجلد يضم ملفاتك — مستندات أو صورًا أو موقعًا إلكترونيًا أو شيفرة. يضيف زر + في تلك القائمة مشروعًا؛ وبعدها يستطيع المساعد فتح هذه الملفات وتعديلها عندما تطلب.",
  "shellintro.toolsPhoneTitle": "الأدوات",
  "shellintro.toolsPhoneBody": "هنا أدواتك. تُفتح كل أداة بملء الشاشة؛ المس «رجوع» للعودة إلى المحادثة.",
  "shellintro.customizePhoneBody": "على الحاسوب، يتيح لك «وضع التعديل» في قائمتك إضافة الأزرار أو إزالتها أو نقلها. وهنا أيضًا تتيح لك الإعدادات اختيار المساعدين ونماذج الذكاء الاصطناعي، والإضافات (الحزم)، وغير ذلك.",
  "composer.manageHarnesses": "إدارة بيئات التشغيل",
  "packages.onboarding.tours.installed.modelsComeFromHarnesses": "تأتي النماذج من بيئات التشغيل لديك",
  "packages.onboarding.tours.installed.polythTalksToModelsThroughHarnesses": "يتواصل Polyth مع النماذج عبر بيئات تشغيل الوكلاء. تعمل نماذج OpenCode المجانية دون حساب. هل تفضّل Claude Code أو Codex أو وكيلًا آخر؟ ثبّت المفضّل لديك واضبطه في صفحة بيئات التشغيل — هذا اختياري.",
  "packages.onboarding.tours.installed.openHarnesses": "فتح بيئات التشغيل",
